@@ -0,0 +1,354 @@
+.page {
+  position: relative;
+  box-sizing: border-box;
+  min-height: 100vh;
+  overflow: hidden;
+  background:
+    linear-gradient(var(--thorp-line) 1px, transparent 1px),
+    linear-gradient(90deg, var(--thorp-line) 1px, transparent 1px),
+    var(--thorp-background);
+  background-size: 72px 72px;
+  color: var(--thorp-foreground);
+}
+
+.ambient {
+  position: absolute;
+  top: -28%;
+  left: 8%;
+  width: 62vw;
+  height: 62vw;
+  border-radius: 50%;
+  background: radial-gradient(circle, rgb(3 199 90 / 17%) 0, rgb(3 199 90 / 4%) 35%, transparent 68%);
+  filter: blur(28px);
+  pointer-events: none;
+}
+
+.header,
+.layout {
+  position: relative;
+  z-index: 1;
+  width: min(100% - 40px, 1320px);
+  margin: 0 auto;
+}
+
+.header {
+  display: flex;
+  min-height: 84px;
+  align-items: center;
+  justify-content: space-between;
+  border-bottom: 1px solid var(--thorp-line);
+}
+
+.wordmark,
+.loginLink,
+.backLink,
+.loginPrompt a {
+  color: inherit;
+  text-decoration: none;
+}
+
+.wordmark {
+  font-size: 1.5rem;
+  font-weight: 760;
+  letter-spacing: -0.055em;
+}
+
+.wordmark span,
+.eyebrow,
+.panelHeading > span,
+.loginPrompt a {
+  color: var(--thorp-accent);
+}
+
+.loginLink,
+.backLink {
+  display: inline-flex;
+  align-items: center;
+  gap: 7px;
+  color: var(--thorp-copy);
+  font-size: 0.76rem;
+  font-weight: 660;
+}
+
+.loginLink:hover,
+.backLink:hover,
+.loginPrompt a:hover {
+  color: var(--thorp-accent-soft);
+}
+
+.layout {
+  display: grid;
+  grid-template-columns: minmax(300px, 0.9fr) minmax(520px, 1.1fr);
+  gap: clamp(48px, 8vw, 124px);
+  align-items: center;
+  min-height: calc(100vh - 85px);
+  padding: 48px 0 64px;
+}
+
+.intro {
+  align-self: start;
+  padding-top: clamp(30px, 9vh, 104px);
+}
+
+.eyebrow {
+  font-size: 0.66rem;
+  font-weight: 760;
+  letter-spacing: 0.2em;
+}
+
+.intro h1 {
+  max-width: 650px;
+  margin: 26px 0 22px;
+  font-size: clamp(2.6rem, 5vw, 5.2rem);
+  font-weight: 560;
+  letter-spacing: -0.07em;
+  line-height: 0.98;
+  outline: none;
+}
+
+.intro h1:focus-visible {
+  border-radius: 4px;
+  box-shadow: 0 0 0 3px rgb(3 199 90 / 28%);
+}
+
+.intro p {
+  max-width: 520px;
+  margin: 0 0 34px;
+  color: var(--thorp-copy);
+  font-size: 0.85rem;
+  line-height: 1.8;
+}
+
+.formPanel {
+  padding: clamp(24px, 3vw, 42px);
+  border: 1px solid var(--thorp-line-strong);
+  background: rgb(7 17 11 / 86%);
+  box-shadow: var(--thorp-shadow);
+  backdrop-filter: blur(18px);
+}
+
+.panelHeading {
+  display: flex;
+  gap: 20px;
+  align-items: flex-start;
+  padding-bottom: 22px;
+  border-bottom: 1px solid var(--thorp-line);
+}
+
+.panelHeading h2:focus {
+  outline: none;
+}
+
+.panelHeading h2:focus-visible {
+  border-radius: 3px;
+  box-shadow: 0 0 0 3px rgb(3 199 90 / 28%);
+}
+
+.stepProgress {
+  display: flex;
+  gap: 6px;
+  align-items: center;
+  margin-left: auto;
+}
+
+.stepProgress span {
+  width: 24px;
+  height: 3px;
+  background: var(--thorp-line-strong);
+}
+
+.stepProgress span[data-active='true'] {
+  background: var(--thorp-accent);
+}
+
+.panelHeading > span {
+  padding-top: 3px;
+  font-size: 0.7rem;
+  font-weight: 760;
+}
+
+.panelHeading h2,
+.panelHeading p {
+  margin: 0;
+}
+
+.panelHeading h2 {
+  font-size: 1.35rem;
+  letter-spacing: -0.035em;
+}
+
+.panelHeading p {
+  margin-top: 4px;
+  color: var(--thorp-muted);
+  font-size: 0.7rem;
+}
+
+.form {
+  display: grid;
+  gap: 18px;
+  padding-top: 24px;
+}
+
+.previewToggle {
+  display: flex;
+  gap: 10px;
+  align-items: flex-start;
+  padding: 11px 12px;
+  border: 1px solid var(--thorp-line);
+  color: var(--thorp-copy);
+  cursor: pointer;
+}
+
+.previewToggle input {
+  margin: 3px 0 0;
+  accent-color: var(--thorp-accent);
+}
+
+.previewToggle span {
+  display: grid;
+  gap: 3px;
+}
+
+.previewToggle strong {
+  color: var(--thorp-foreground);
+  font-size: 0.72rem;
+}
+
+.previewToggle small {
+  color: var(--thorp-muted);
+  font-size: 0.66rem;
+}
+
+.verificationSection {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) 142px;
+  gap: 10px;
+  align-items: end;
+}
+
+.fieldGrid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 18px 14px;
+}
+
+.stepSummary {
+  display: flex;
+  gap: 10px;
+  align-items: center;
+  padding-bottom: 18px;
+  border-bottom: 1px solid var(--thorp-line);
+  color: var(--thorp-positive);
+}
+
+.stepSummary span {
+  display: grid;
+  gap: 3px;
+  color: var(--thorp-muted);
+  font-size: 0.66rem;
+}
+
+.stepSummary strong {
+  color: var(--thorp-foreground);
+  font-size: 0.78rem;
+}
+
+.formActions {
+  display: grid;
+  grid-template-columns: minmax(120px, 0.4fr) minmax(0, 1fr);
+  gap: 10px;
+}
+
+.formActions button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+}
+
+.verifiedLabel {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  color: var(--thorp-positive);
+  font-size: 0.72rem;
+  font-weight: 650;
+}
+
+.form > button[type='submit'] {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 9px;
+}
+
+.loginPrompt {
+  margin: 20px 0 0;
+  color: var(--thorp-muted);
+  font-size: 0.72rem;
+  text-align: center;
+}
+
+.loginPrompt a {
+  font-weight: 720;
+}
+
+.wordmark:focus-visible,
+.loginLink:focus-visible,
+.backLink:focus-visible,
+.loginPrompt a:focus-visible {
+  border-radius: 4px;
+  outline: 3px solid rgb(3 199 90 / 30%);
+  outline-offset: 3px;
+}
+
+@media (max-width: 900px) {
+  .layout {
+    grid-template-columns: 1fr;
+    gap: 36px;
+    align-items: start;
+  }
+
+  .intro {
+    padding-top: 28px;
+  }
+
+  .intro h1 {
+    font-size: clamp(2.5rem, 10vw, 4.5rem);
+  }
+
+  .intro p {
+    margin-bottom: 20px;
+  }
+}
+
+@media (max-width: 560px) {
+  .header,
+  .layout {
+    width: min(100% - 28px, 1320px);
+  }
+
+  .layout {
+    padding-top: 30px;
+  }
+
+  .intro h1 {
+    margin-top: 20px;
+  }
+
+  .formPanel {
+    padding: 22px 18px;
+  }
+
+  .verificationSection,
+  .fieldGrid,
+  .formActions {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .ambient {
+    filter: none;
+  }
+}

